import json, urllib.request, re

with open('/home/user/.gitconfig', 'r') as f:
    gitconfig = f.read()
match = re.search(r'x-access-token:([^@]+)@github\.com/ibb142/ivx-holdings-platform', gitconfig)
github_token = match.group(1)
REPO = "ibb142/ivx-holdings-platform"

def gh(method, path, payload=None, expect_json=True):
    url = f"https://api.github.com/repos/{REPO}/{path}"
    headers = {
        'Authorization': f'token {github_token}',
        'Accept': 'application/vnd.github+json',
        'Content-Type': 'application/json'
    }
    data = json.dumps(payload).encode() if payload else None
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            body = resp.read()
            if resp.status == 204 or not body:
                return {'status': resp.status}
            return json.loads(body.decode()) if expect_json else body.decode()
    except urllib.error.HTTPError as e:
        body = e.read().decode()
        try:
            err = json.loads(body)
        except:
            err = body
        return {'error': True, 'status': e.code, 'message': err}

print("=== Main HEAD ===")
head = gh('GET', 'branches/main')
print(f"Main HEAD: {head['commit']['sha']}")
print(f"Commit message: {head['commit']['commit']['message'][:100]}")

print("\n=== Branch protection status ===")
prot = gh('GET', 'branches/main/protection')
if 'error' in prot:
    print(f"Protection check error: {prot}")
else:
    print(f"Protection enabled: {prot.get('enabled', 'N/A')}")
    rpr = prot.get('required_pull_request_reviews')
    if rpr:
        print(f"Required approving reviews: {rpr.get('required_approving_review_count')}")
    else:
        print("No required pull request reviews")
    ea = prot.get('enforce_admins')
    if ea:
        print(f"Enforce admins: {ea.get('enabled')}")
    else:
        print("No enforce admins info")

print("\n=== Fixed file on main ===")
file_info = gh('GET', 'contents/backend/api/ivx-developer-deploy-control.ts?ref=main')
print(f"File size: {file_info.get('size')} bytes")
print(f"File SHA: {file_info.get('sha')}")
PYEOF

